      { q: "'एक आशीर्वाद' कविता के कवि कौन हैं?", options: ["महादेवी वर्मा", "दुष्यंत कुमार", "गिरिजाकुमार माथुर", "गयाप्रसाद शुक्ल 'सनेही'"], answer: 1, explain: "यह कविता दुष्यंत कुमार की है।", level: 1 },
      { q: "दुष्यंत कुमार का जन्म कहाँ हुआ?", options: ["इटावा", "काशी", "बिजनौर", "दमोह"], answer: 2, explain: "उनका जन्म बिजनौर (उत्तर प्रदेश) में हुआ।", level: 1 },
      { q: "'साये में धूप' क्या है?", options: ["ग़ज़ल-संग्रह", "उपन्यास", "नाटक", "निबंध-संग्रह"], answer: 0, explain: "यह दुष्यंत कुमार का प्रसिद्ध ग़ज़ल-संग्रह है।", level: 1 },
      { q: "कविता में कवि किसे आशीर्वाद दे रहा है?", options: ["वृद्ध को", "किसान को", "सैनिक को", "बच्चे या युवा को"], answer: 3, explain: "'जा, तेरे स्वप्न बड़े हों' – संबोधन छोटे/युवा के लिए है।", level: 1 },
      { q: "'स्वप्न' शब्द का अर्थ क्या है?", options: ["नींद", "सपना", "रात", "थकान"], answer: 1, explain: "स्वप्न यानी सपना।", level: 1 },
      { q: "'अपने पाँवों पर खड़े हों' का आशय क्या है?", options: ["बहुत देर खड़े रहना", "तेज़ दौड़ना", "आत्मनिर्भर बनना", "पैदल चलना"], answer: 2, explain: "यह आत्मनिर्भर होने का भाव है।", level: 2 },
      { q: "'उँगली जलाएँ' से कवि क्या कहना चाहता है?", options: ["चुनौतियों में कष्ट सहकर भी आगे बढ़ना", "आग से खेलना", "असावधानी बरतना", "खाना बनाना"], answer: 0, explain: "लक्ष्य की ललक में कष्ट आए तो भी घबराना नहीं चाहिए।", level: 2 },
      { q: "'भावना की गोद से उतरकर धरती पर चलना सीखें' का आशय है –", options: ["गोद से उतरकर खेलना", "भावुक होना", "भावनाओं से दूर रहना", "कल्पना से यथार्थ की ज़मीन पर आना"], answer: 3, explain: "सपनों के साथ यथार्थ का सामना करना भी ज़रूरी है।", level: 2 },
      { q: "'रूठना-मचलना' सीखने का भाव क्या है?", options: ["बिगड़ जाना", "अपनी बड़ी चाहत के लिए ज़िद और लगन रखना", "बात-बात पर रोना", "दूसरों पर निर्भर होना"], answer: 1, explain: "चाँद-तारों जैसी ऊँची चीज़ों के लिए भी हठ और लगन ज़रूरी है।", level: 2 },
      { q: "'स्वप्न' शब्द व्याकरण की दृष्टि से क्या है?", options: ["क्रिया", "विशेषण", "संज्ञा", "सर्वनाम"], answer: 2, explain: "स्वप्न एक भाव/वस्तु का नाम है, इसलिए संज्ञा है।", level: 2 },
      { q: "कवि को कैसा बच्चा अपेक्षित है?", options: ["जो केवल कल्पना में खोया रहे", "जिसके कोई सपने न हों", "जो केवल दूसरों के सपनों पर चले", "जो बड़े सपने देखे और उन्हें साकार करने के लिए संघर्ष करे"], answer: 3, explain: "कविता में बड़े सपनों के साथ कर्म और चुनौती स्वीकारने की बात है।", level: 3 },
      { q: "रोहन के जन्मदिन पर पिता ने कहा, 'तुम्हारे सपने बड़े हों और तुम अपने पैरों पर खड़े हो सको।' यह शुभकामना कविता के किस भाव के निकट है?", options: ["आशीर्वाद का भाव – बड़े सपने और आत्मनिर्भरता", "चेतावनी का भाव", "आदेश का भाव", "निंदा का भाव"], answer: 0, explain: "कविता भी बड़े सपनों और आत्मनिर्भरता का आशीर्वाद देती है।", level: 3 },
      { q: "'चाँद-तारों-सी अप्राप्य सच्चाइयों के लिए रूठना-मचलना' का आशय क्या है?", options: ["चाँद माँगते रहना", "कठिन से कठिन लक्ष्य के लिए भी ज़िद और लगन रखना", "बचपन में ही रह जाना", "खिलौनों की माँग करना"], answer: 1, explain: "अप्राप्य लक्ष्य के प्रति भी प्रबल चाह कवि को प्रिय है।", level: 3 },
      { q: "आरुषि इंजीनियर बनना चाहती है। गणित कठिन लगता है, फिर भी वह रोज़ अतिरिक्त अभ्यास करती है। उसमें कविता का कौन-सा भाव दिखता है?", options: ["निराशा", "आराम पसंद करना", "बड़े सपने के लिए लगन और कठिनाई से न घबराना", "दूसरों पर निर्भरता"], answer: 2, explain: "बड़े सपने के लिए लगन और चुनौती स्वीकार करना कविता का भाव है।", level: 3 }
